public static String applyRelativePath(String path, String relativePath) {
    if (path == null) path = "";
    if (relativePath == null) relativePath = "";
    // Determine the base directory from the given path
    String baseDir;
    if (path.isEmpty()) {
        baseDir = "";
    } else {
        if (path.endsWith("/")) {
            baseDir = path;
        } else {
            int lastSlash = path.lastIndexOf('/');
            if (lastSlash >= 0) {
                baseDir = path.substring(0, lastSlash + 1);
            } else {
                baseDir = "";
            }
        }
    }
    // Combine base directory with the relative path
    String combined = baseDir + relativePath;
    boolean leadingSlash = combined.startsWith("/");
    // Split into components and normalize
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!leadingSlash) {
                // Preserve leading ".." when not rooted
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }
    // Reconstruct the normalized path
    StringBuilder sb = new StringBuilder();
    if (leadingSlash) sb.append("/");
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) sb.append("/");
    }
    return sb.toString();
}

