        char c = pat.charAt(i);
        if (c == '%') {
            if (i + 1 < pat.length()) {
                char next = pat.charAt(i + 1);
                switch (next) {
                    case 'm':
                        Object msg = event.getMessage();
                        sb.append(msg != null ? msg.toString() : "null");
