    if (rect != null) {
        table.scrollRectToVisible(rect);
    }
    // Delay repaint to allow the table to paint the newly selected row
    SwingUtilities.invokeLater(() -> {
        SwingUtilities.invokeLater(() -> table.repaint());
    });
}

