public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the contents of the current buffer segment
        out.write(node.data, 0, node.size);
        totalSize += node.size;
        node = node.next;
    }
    return totalSize;
}

