private void checkIfPackedField() throws IOException {
    // Only consider length-delimited fields for packed data
    if (currentWireType == WIRETYPE_LENGTH_DELIMITED) {
        // If we are not already processing a packed field, start one
        if (packedFieldNumber == 0) {
            // Record the field number that is packed
            packedFieldNumber = currentFieldNumber;
            // Read the length of the packed data
            packedFieldLength = input.readRawVarint32();
            // Compute the end position of the packed data
            packedFieldEnd = input.getPosition() + packedFieldLength;
            // Reset the index for reading individual packed values
            packedFieldIndex = 0;
        }
    }
}

